func TestAStateColouredSelectionKeepsItsHighlightToTheEnd(t *testing.T) {
	withTrueColor(t)
	m := colouredTable(t)
	m.cfg.SelectedStyles = func(row) table.Styles { return theme.TableStylesForState("error") }
